properties.property:
[
	{
		"name": "",
		"text": "You approach what seems to be a building for the stockpiling of food. Several people stand outside on guard, covered in sting-marks and swatting away swarms of bees. 'Please, adventurer, we need help!'",
		"options":
			[
				{
					"name": "Just as you please, here's some cheese for your bees.",
                    "text": "The guards lift the cheese aloft and the insects fly away at their command. 'Glorious relief! Oh how we thank you! And all the townsfolk give their thanks too. Now we won't starve come winter.'",
					"action": [ { "deleteMapObject": -1 },
                    {"grantRewards": [
						{"type": "life", "count": 1},
						{ "type": "card", "cardName": "The Cheese Stands Alone", "count": 1 },
						{ "type": "card", "cardName": "Killer Bees", "count": 1 },
						{ "type": "card", "cardName": "Unyaro Bees", "count": 1 },
						{ "type": "card", "cardName": "Unyaro Bee Sting", "count": 1 },
						{ "type": "card", "cardName": "Bee Sting", "count": 1 },
                        {"type": "gold", "count": 1000}          
                      ]
                    },
					{"removeItem":"Cheese of Bees"},
					{"addMapReputation": 2}  ],
					"condition":[{"item":"Cheese of Bees"}], 
					"options": [ { "name": "(Continue)" } ]
				},
				{
					"name": "What's the trouble? Other than the bees?",
					"text": "'Well that's just the thing it IS the bees! And wasps, and hornets, and I don't even want to think about what else! Damn bugs getting into our food supplies. We've discovered that it's no coincidence, they're being led by this nasty assassin lady, Xira Arien. We need someone to take her out and retrieve her cheese of bees.'",
					"options": [ { "name": "Her... what?",
					"text": "'The cheese of bees! It's an enchanted hunk of cheese that commands bees! And other such bugs we're pretty sure but its not like we have it around to test out. Anyway, retrieve the cheese and stop the swarms and we'll give you the town's blessing, and some money to boot. Her hive is a huge rib-cage looking thing. Can't miss it.'",
					"options": [ { "name": "I'll bee what I can do." } ]
					 }]
				},
                {
					"name": "I don't have time for this.",
					"text": "You leave the guards to bee stung.",
					"options": [ { "name": "(Continue)" } ]
				}
			]
	}
]

[
	{
		"name": "",
		"text": "A council of rather grim-looking elves stand over a table, pouring over various maps. 'If you think you can handle a truly fearsome foe, we have a bounty for you. Otherwise, leave us.'",
		"options":
			[
				{
					"name": "Vorinclex has been slain.",
                    "text": "'Incredible. Truly an impressive feat. All the forests are safer thanks to your heroism.'",
					"action": [ { "deleteMapObject": -1 },
                    {"grantRewards": [
						{"type": "life", "count": 1},
						{ "type": "card", "cardName": "Heroic Intervention", "count": 1 },
                        {"type": "gold", "count": 5000}          
                      ]
                    },
					{"removeItem":"Green Cartouche of Victory"},
					{"addMapReputation": 4}  ],
					"condition":[{"item":"Green Cartouche of Victory"}], 
					"options": [ { "name": "(Continue)" } ]
				},
				{
					"name": "No foe is too fearsome for me.",
					"text": "'I certainly hope you can back up your boasts, or you'll be worse than dead - you may end up as one of the enemy. Yes, the one causing us such trouble right now is none other than the Phyrexian Praetor Vorinclex himself.'",
					"options": [ { "name": "A fearsome foe indeed.",
					"text": "'Yes. His lair is a fortress of copper. His minions wield vicious poison and crushing strength, to say nothing of their leader. Defeat him and the town's blessing will be well-earned, and we shall pay you handsomely as well.'",
					"options": [ { "name": "I'm on the job." } ]
					 }]
				},
                {
					"name": "I'll just leave you folks to it then.",
					"text": "You walk away quietly.",
					"options": [ { "name": "(Continue)" } ]
				}
			]
	}
]

[
	{
		"name": "",
		"text": "You approach a circle of druids standing around a sacred fountain. 'Hail, traveler! We are in need of a mighty hero to retrieve a sacred relic for us.'",
		"options":
			[
				{
					"name": "One clover. Still intact somehow, if rather sticky.",
                    "text": "The druids rejoice. 'Wonderful! We knew that the clover would be lucky enough to survive digestion! And now favor will shine on our town again, as we hope it shines on you!'",
					"action": [ { "deleteMapObject": -1 },
                    {"grantRewards": [
						{"type": "life", "count": 1},
						{ "type": "card", "cardName": "As Luck Would Have It", "count": 1 },
						{ "type": "card", "cardName": "Wish Good Luck", "count": 1 },
						{ "type": "card", "cardName": "Lucky Clover", "count": 1 },
                        { "type": "card", "cardName": "Good-Fortune Unicorn", "count": 1 },
                        { "type": "card", "cardName": "Family's Favor", "count": 1 },
						{ "type": "card", "cardName": "Make Your Own Luck", "count": 1 },
                        {"type": "gold", "count": 3000}          
                      ]
                    },
					{"removeItem":"The Luckiest Clover"},
					{"addMapReputation": 4}  ],
					"condition":[{"item":"The Luckiest Clover"}], 
					"options": [ { "name": "(Continue)" } ]
				},
				{
					"name": "A mighty hero? That sounds like me.",
					"text": "'Excellent! You see, we druids are responsible for keeping up our great capitols magical wards. A few weeks back, a massive hydra besieged our city. The wards held, but one stray head managed to pluck our luckiest clover, and we need it back.'",
					"options": [ { "name": "You want me to retrieve a clover?",
					"text": "'Not just any clover, our luckiest clover. No, THE luckiest clover! Our magic might be strong, but to survive all the perils of this forsaken world, one needs luck on their side, and that was what our clover gave us. Fish it out of the belly of Gargos from its lake lair, and you'll have our blessing.'",
					"options": [ { "name": "Well, we'll see if I get lucky." } ]
					 }]
				},
                {
					"name": "Not sure I'm up for that.",
					"text": "'Be well traveller, and may what luck you can find guide you.'",
					"options": [ { "name": "(Continue)" } ]
				}
			]
	}
]

[
	{
		"name": "",
		"text": "You step inside a hollow tree, surprisingly large on the inside. A great dryad (or perhaps an elemental? Or a treefolk?) emerges from an interior wall of the tree. 'Hail, adventurer. I seek a truly impressive hero. Is that you?'",
		"options":
			[
				{
					"name": "The three great threats are ended.",
                    "text": "'All the forests are forever in your debt!'",
					"action": [ { "deleteMapObject": -1 },
                    {"grantRewards": [
		      {"type": "item", "count": 1, "itemName": "Helm of Myth"},
                        {"type": "card", "count": 1, "cardName": "Gaea's Cradle"},
                        {"type": "card", "count": 1, "cardName": "Worldly Tutor"}             
                      ]
                    },
					{"addMapReputation": 10}  ],
					"condition":[{"item": "Acorn Amulet"}, {"item": "Strider Reins"}, {"item": "Joraga Boots"}], 
					"options": [ { "name": "(Continue)" } ]
				},
				{
					"name": "It certainly might be.",
					"text": "'As you know, a great number of fearsome legends menace these lands. I have three great treasures to offer to one who can defeat all three of the greatest threats facing the forest.'",
					"options": [ { "name": "Which three are we speaking of?",
					"text": "'The primal calamity, Zacama. The worldshaker, Nissa. And the commander of the endless squirrel legions, Chatterfang. Show me the relics they drop upon their defeat, and the great rewards and true adoration of the city will be yours.'",
					"options": [ { "name": "I will see what I can do." } ]
					 }]
				},
                {
					"name": "Well I'm impressive, but not THAT impressive.",
					"text": "'Wise of you to know your limits.'",
					"options": [ { "name": "(Continue)" } ]
				}
			]
	}
]
